/* OBRASST · la biblioteca de normas de la app, para el portal: el Perú con sus
   fichas y los demás países con su obligación y el enlace al texto oficial.
   Lo arma armar.py desde la app. No editar. */
var NORMAS_WEB = {"pe":[{"t":"Ley 29783","d":"Ley de Seguridad y Salud en el Trabajo","p":"La ley madre de la SST en el Perú. Fija el deber de prevención del empleador y los derechos del trabajador. Todo lo demás cuelga de aquí.","obliga":["Tener un Sistema de Gestión de SST, con política escrita y firmada por la máxima autoridad.","Identificar peligros y evaluar riesgos (IPERC) y actualizarlo cuando cambien las condiciones.","Capacitar al trabajador: al ingresar, al cambiar de puesto y cuando cambie la tecnología. Mínimo 4 capacitaciones al año.","Constituir el Comité de SST si tienes 20 o más trabajadores; si son menos, un Supervisor de SST.","Llevar los registros obligatorios: accidentes, enfermedades, exámenes médicos, monitoreos, inspecciones, capacitaciones y entrega de EPP.","Entregar EPP sin costo y reponerlo cuando se deteriore.","Practicar exámenes médicos ocupacionales de ingreso, periódicos y de retiro.","Investigar todo accidente e incidente peligroso y tomar medidas correctivas."],"revisa":["Que la política esté firmada, fechada y publicada donde el trabajador la vea.","Que el IPERC esté firmado y que corresponda a lo que realmente se hace en obra.","Las actas del comité y que se reúna al menos una vez al mes.","Los registros con firma del trabajador, no listas sin firmar."],"ojo":"El incumplimiento lo sanciona SUNAFIL, y en accidente grave o mortal hay responsabilidad penal para el empleador (artículo 168-A del Código Penal)."},{"t":"D.S. 005-2012-TR","d":"Reglamento de la Ley 29783","p":"El reglamento que dice CÓMO cumplir la ley: plazos, contenidos mínimos, cómo se compone el comité y qué debe decir cada registro.","obliga":["Elaborar el Reglamento Interno de SST (RISST) si tienes 20 o más trabajadores, y entregarlo a cada uno.","Hacer el Programa Anual de SST con objetivos, metas, responsables y presupuesto.","Elegir el comité por votación, con igual número de representantes del empleador y de los trabajadores.","Usar los formatos de registro con la información mínima que exige el anexo.","Dar inducción al trabajador nuevo antes de que empiece a trabajar."],"revisa":["Que el RISST esté entregado con cargo firmado.","El programa anual con su avance real, no solo el plan.","Que los registros usen la información mínima del anexo del reglamento."],"ojo":"Los registros pueden llevarse en medio físico o digital, pero tienen que poder mostrarse cuando el inspector los pida."},{"t":"Ley 30222","d":"Modificatoria de la Ley 29783","p":"Ajustó varios artículos de la 29783: flexibilizó algunas exigencias y cambió el régimen de fiscalización y sanciones.","obliga":["Los exámenes médicos periódicos pasaron a cada 2 años para trabajo de riesgo (antes anual).","El empleador puede contratar los servicios de SST de forma externa, sin dejar de ser responsable.","La capacitación debe darse dentro de la jornada de trabajo."],"revisa":["Que la capacitación no se dicte fuera de horario ni con cargo al trabajador."],"ojo":"Que se haya flexibilizado no quita la responsabilidad: el deber de prevención del empleador sigue completo."},{"t":"Norma G.050 (RNE)","d":"Seguridad durante la construcción","p":"La norma de obra. Es la que más se usa en el día a día del prevencionista en construcción: qué EPP, cómo se señaliza, cómo se arma un andamio, cómo se excava.","obliga":["EPP básico obligatorio en toda obra: casco, lentes, zapatos de seguridad y chaleco reflectivo.","Andamios con plataforma completa, barandas, rodapié y arriostres; armados y revisados por persona competente.","Excavaciones de más de 1.50 m con talud, entibado o sistema de protección, y accesos cada 7.50 m.","Barandas en todo borde con caída de más de 1.80 m.","Señalización y delimitación de las zonas de trabajo y de circulación.","ATS (Análisis de Trabajo Seguro) antes de la tarea, firmado por los que la van a hacer.","Orden y limpieza permanentes; escaleras aseguradas y sobresaliendo 1.00 m del punto de llegada."],"revisa":["Que el ATS esté firmado por la cuadrilla ese mismo día, no de la semana pasada.","Andamios con tarjeta de inspección (verde/roja) y armados completos.","Que el arnés esté anclado por encima del hombro y a un punto que resista."],"ojo":"Trabajo en altura en construcción se cuenta desde 1.80 m. En otras actividades el criterio puede ser 1.80 m también, pero revisa el sector."},{"t":"D.S. 011-2019-TR","d":"Reglamento de SST en Construcción","p":"Reglamento sectorial exclusivo de construcción civil. Detalla lo que la G.050 pide, y agrega obligaciones de gestión propias del sector.","obliga":["Plan de Seguridad y Salud en el Trabajo específico para cada obra, antes de empezar.","Un profesional de SST a cargo, con las horas y el perfil que exige la norma según el monto de la obra.","Charlas de inducción a todo el que entra a obra, incluidos visitantes y subcontratistas.","Coordinar la SST con todos los subcontratistas: el contratista principal responde.","Botiquín, camilla y personal entrenado en primeros auxilios en obra."],"revisa":["El Plan de SST de la obra, firmado y con su presupuesto.","Los cargos de inducción de TODO el que está en obra, incluidos los del subcontratista.","Que el profesional de SST realmente esté en obra las horas que corresponden."],"ojo":"El contratista principal responde por la seguridad de los trabajadores de sus subcontratistas. No sirve decir \"ese no es mi personal\"."},{"t":"D.S. 024-2016-EM","d":"Reglamento de SSO en Minería","p":"La norma de minería. Mucho más exigente que construcción en permisos, IPERC y competencias.","obliga":["IPERC de línea base, específico y CONTINUO (el continuo se llena antes de cada tarea, en el mismo lugar).","PETS escritos para toda tarea, y PETAR para trabajos de alto riesgo.","Capacitación mínima de 4 horas trimestrales para todo trabajador y las horas específicas del anexo.","Programa de capacitación anual aprobado por el comité."],"revisa":["IPERC continuo del día, firmado por los que ejecutan.","PETAR vigente y con las firmas de autorización completas.","Las horas de capacitación por trabajador contra el anexo."],"ojo":"El IPERC continuo es de minería. Si estás en construcción, no confundas: allí lo que se pide es el ATS."},{"t":"D.S. 023-2017-EM","d":"Modificatoria del 024-2016-EM","p":"Ajustes al reglamento de seguridad minera: cambió plazos, algunos anexos y precisó obligaciones del titular minero.","obliga":["Revisar los anexos actualizados de capacitación y de los registros.","Precisiones sobre la responsabilidad del titular minero frente a contratistas."],"revisa":["Que se estén usando los anexos vigentes, no los del 024 original."],"ojo":"Siempre lee el 024-2016-EM junto con esta modificatoria: solos, cada uno está incompleto."},{"t":"D.S. 003-98-SA","d":"Seguro Complementario de Trabajo de Riesgo (SCTR)","p":"Obliga a asegurar al trabajador que hace actividad de riesgo, con dos coberturas: salud y pensión.","obliga":["Contratar SCTR SALUD y SCTR PENSIÓN para todo trabajador en actividad de riesgo (construcción lo es).","Mantener la póliza vigente durante todo el tiempo que el trabajador esté en obra.","Declarar mensualmente a los trabajadores cubiertos."],"revisa":["La póliza vigente y el listado del mes con TODOS los que están en obra.","Que los del subcontratista también estén cubiertos."],"ojo":"Un trabajador sin SCTR en obra es de las observaciones más caras y más frecuentes. Revísalo cada mes, no al inicio nomás."},{"t":"R.M. 312-2011-MINSA","d":"Protocolos de exámenes médicos ocupacionales","p":"Define qué exámenes se hacen según el puesto y el riesgo, y con qué frecuencia.","obliga":["Examen de ingreso, periódico y de retiro, según el puesto.","Exámenes específicos por riesgo: altura, espacios confinados, manejo de equipos, exposición a polvo o ruido.","Entregar al trabajador el resultado de su examen.","Guardar la aptitud médica, no el diagnóstico: el detalle clínico es reservado."],"revisa":["El certificado de aptitud vigente de cada trabajador, sobre todo de los que trabajan en altura.","Que el examen corresponda al puesto real, no uno genérico."],"ojo":"El empleador guarda la APTITUD (apto / apto con restricciones / no apto). El diagnóstico médico es confidencial y no debe estar en el file del trabajador."},{"t":"R.M. 375-2008-TR","d":"Norma básica de ergonomía","p":"Fija los límites y las buenas prácticas de manipulación de carga, posturas y puestos de trabajo.","obliga":["Límite de carga manual: 25 kg para varones y 15 kg para mujeres en condiciones normales.","Evaluar los puestos con riesgo disergonómico y aplicar medidas de control.","Capacitar en manipulación manual de cargas y posturas."],"revisa":["La evaluación ergonómica de los puestos críticos.","Que existan ayudas mecánicas donde la carga supera el límite."],"ojo":"Los trastornos musculoesqueléticos son la enfermedad ocupacional más declarada en el Perú. No es un tema menor."},{"t":"Ley 28806 / D.S. 019-2006-TR","d":"Inspección del trabajo y sus sanciones","p":"Regula cómo actúa SUNAFIL y cuánto cuesta incumplir. Es la parte que le importa a gerencia.","obliga":["Atender la inspección y entregar la documentación que se pida.","No obstruir la labor del inspector: eso ya es una infracción por sí sola.","Subsanar dentro del plazo del requerimiento."],"revisa":["Que el file de SST esté disponible el mismo día de la visita.","Los registros obligatorios completos y firmados."],"ojo":"Las infracciones muy graves en SST llegan a decenas de UIT, y se multiplican por el número de trabajadores afectados."},{"t":"D.S. 006-2014-TR","d":"Modificatorias al reglamento de la Ley","p":"Ajustó varios artículos del D.S. 005-2012-TR, sobre todo en registros, comité y documentación.","obliga":["Usar los formatos de registro actualizados.","Precisiones sobre la vigencia y renovación del comité de SST."],"revisa":["Que los formatos que usas sean los vigentes."],"ojo":"Léelo siempre junto al D.S. 005-2012-TR: modifica artículos puntuales, no lo reemplaza."},{"t":"R.M. 571-2014-MINSA","d":"Modifica los protocolos de exámenes médicos ocupacionales","p":"Cambia partes de la R.M. 312-2011-MINSA: ajusta protocolos y guías de diagnóstico.","obliga":["Aplicar los protocolos con la modificación vigente, no la versión original de 2011."],"revisa":["Que el proveedor de exámenes médicos esté usando la versión modificada."],"ojo":"La R.M. 312-2011-MINSA sola está incompleta. Se lee junto con esta."},{"t":"D.S. 043-2007-EM","d":"Reglamento de Seguridad para las Actividades de Hidrocarburos","p":"Es el reglamento de seguridad del sector hidrocarburos: exploración, producción, transporte, refino, almacenamiento y comercialización.","obliga":["Permisos de trabajo escritos para trabajo en caliente, espacios confinados, excavaciones y trabajos eléctricos.","Clasificación de áreas peligrosas y equipos acordes a esa clasificación.","Plan de contingencias y respuesta a emergencias del establecimiento."],"revisa":["Los permisos de trabajo firmados por quien corresponde, no en blanco.","Que el personal de contratista tenga la misma inducción que el propio."],"ojo":"En hidrocarburos el permiso de trabajo no es papeleo: es la barrera. Un PT mal llenado es hallazgo por sí solo."},{"t":"R.M. 111-2013-MEM/DM","d":"RESESATE · Seguridad y salud con electricidad","p":"Reglamento de Seguridad y Salud en el Trabajo con Electricidad. Aplica a toda actividad eléctrica, no solo a las eléctricas.","obliga":["Las cinco reglas de oro antes de trabajar en una instalación sin tensión.","EPP dieléctrico certificado y vigente según el nivel de tensión.","Personal calificado y autorizado por escrito para maniobras."],"revisa":["Los certificados de los guantes dieléctricos y su fecha de reensayo.","El procedimiento de bloqueo y señalización (LOTO) aplicado de verdad."],"ojo":"La mayoría de accidentes eléctricos graves ocurren en trabajos que se creían sin tensión. Verificar ausencia de tensión no es opcional."},{"t":"R.M. 214-2011-MEM/DM","d":"Resolución que aprueba el CNE · Suministro 2011","p":"Es la resolución que pone en vigencia el Código Nacional de Electricidad · Suministro 2011. El Código en sí —líneas, subestaciones y distancias de seguridad— es un documento aparte, de cientos de páginas.","obliga":["Respetar las distancias mínimas de seguridad a líneas energizadas, que fija el Código."],"revisa":["Las distancias en obra cuando hay grúas, andamios o encofrados cerca de una línea."],"ojo":"El PDF que tengo cargado es la resolución de dos páginas, no el Código completo: del Suministro 2011 no encontré una descarga oficial del texto íntegro. El de Utilización sí está entero, más abajo."},{"t":"R.M. 037-2006-MEM/DM","d":"Resolución que aprueba el CNE · Utilización","p":"Es la resolución que pone en vigencia el Código Nacional de Electricidad · Utilización. El Código completo está cargado aparte, entero.","obliga":["Tableros, protecciones diferenciales y puesta a tierra según lo que exige el Código."],"revisa":["El tablero de obra: diferencial operativo, pozo a tierra con su medición vigente."],"ojo":"Este PDF es la resolución de dos páginas. Para el articulado busca «CNE Utilización 2006», que sí trae las 836 páginas."},{"t":"CNE Utilización 2006","d":"Código Nacional de Electricidad · Utilización, texto completo","p":"El Código entero: 836 páginas de reglas técnicas para las instalaciones eléctricas de utilización — conductores, tableros, protecciones, puesta a tierra, y las secciones especiales (obras, ambientes húmedos, cercos eléctricos, salas de máquinas).","obliga":["Tableros, protecciones diferenciales y puesta a tierra según la sección que corresponda.","Secciones especiales cuando el ambiente lo exige: húmedo, con polvo combustible, con riesgo de explosión."],"revisa":["El tablero provisional de obra: diferencial que dispara, pozo a tierra con medición vigente.","Que el proyecto eléctrico cite la sección del Código, no un criterio del instalador."],"ojo":"Pesa 10 MB: bájalo con wifi, no con datos en obra. La lupa sí busca dentro sin bajar el PDF entero."},{"t":"D.S. 015-2005-SA","d":"Valores límite permisibles para agentes químicos","p":"Fija los valores límite de exposición a agentes químicos en el ambiente de trabajo.","obliga":["Monitorear los agentes químicos a los que está expuesto el personal.","Comparar el resultado del monitoreo contra el valor límite y actuar si se supera."],"revisa":["El informe de monitoreo ocupacional y su fecha."],"ojo":"Sin monitoreo no hay forma de sostener que estás por debajo del límite. La hoja MSDS sola no lo demuestra."},{"t":"D.S. 085-2003-PCM","d":"Estándares nacionales de calidad ambiental para ruido","p":"Fija los estándares de ruido ambiental por zona y horario. Es ambiental, no ocupacional, pero en obra urbana se cruza con la licencia municipal.","obliga":["No superar el estándar de la zona donde estás trabajando."],"revisa":["El monitoreo de ruido cuando hay vecinos o la municipalidad lo pide."],"ojo":"El ruido ocupacional (el del oído del trabajador) se rige por otra norma. Este es el del entorno."},{"t":"Ley 30102","d":"Medidas preventivas contra la radiación solar","p":"Obliga a proteger de la radiación solar a quien trabaja expuesto al sol.","obliga":["Proveer protector solar, y elementos que den sombra o cubran, al personal expuesto.","Informar y sensibilizar sobre el riesgo de la radiación ultravioleta."],"revisa":["Que el bloqueador esté disponible y se entregue, no solo comprado."],"ojo":"En obra a cielo abierto esto se olvida siempre. Y el cáncer de piel ocupacional sí se reconoce."},{"t":"R.M. 050-2013-TR","d":"Formatos referenciales de los registros del SGSST","p":"Trae los formatos referenciales de los registros obligatorios y la guía básica del sistema de gestión.","obliga":["Llevar los registros obligatorios; los formatos son referenciales, el contenido mínimo no."],"revisa":["Que cada registro tenga al menos los campos que pide el formato referencial."],"ojo":"Puedes usar tu propio formato, pero si le falta un campo del referencial, el inspector lo observa."},{"t":"D.L. 1278","d":"Ley de Gestión Integral de Residuos Sólidos","p":"Regula cómo se manejan los residuos, incluidos los peligrosos que genera una obra.","obliga":["Segregar en la fuente y almacenar los residuos peligrosos separados.","Entregar los residuos peligrosos a una EO-RS autorizada y guardar el manifiesto."],"revisa":["El manifiesto de manejo de residuos peligrosos firmado.","El punto de acopio señalizado y con contención."],"ojo":"Trapos con hidrocarburo, envases de pintura y baterías son residuo peligroso. Botarlos con el desmonte es infracción."},{"t":"D.S. 014-2017-MINAM","d":"Reglamento del D.L. 1278","p":"Desarrolla la ley de residuos sólidos: obligaciones del generador, del transportista y de la EO-RS.","obliga":["Declaración anual de manejo de residuos sólidos cuando corresponde.","Plan de minimización y manejo de residuos."],"revisa":["Que la EO-RS contratada esté vigente en el registro autoritativo."],"ojo":"Contratar a una EO-RS con registro vencido te deja a ti como responsable del residuo."}],"meta":{"Ley 29783":{"esp":"Marco legal","sec":"*"},"D.S. 005-2012-TR":{"esp":"Marco legal","sec":"*"},"Ley 30222":{"esp":"Marco legal","sec":"*"},"D.S. 006-2014-TR":{"esp":"Marco legal","sec":"*"},"R.M. 050-2013-TR":{"esp":"Marco legal","sec":"*"},"Norma G.050 (RNE)":{"esp":"Construcción","sec":"construccion"},"D.S. 011-2019-TR":{"esp":"Construcción","sec":"construccion"},"D.S. 024-2016-EM":{"esp":"Minería","sec":"mineria"},"D.S. 023-2017-EM":{"esp":"Minería","sec":"mineria"},"D.S. 043-2007-EM":{"esp":"Hidrocarburos","sec":"hidrocarburos"},"R.M. 111-2013-MEM/DM":{"esp":"Eléctrico","sec":"*"},"R.M. 214-2011-MEM/DM":{"esp":"Eléctrico","sec":"*"},"R.M. 037-2006-MEM/DM":{"esp":"Eléctrico","sec":"*"},"CNE Utilización 2006":{"esp":"Eléctrico","sec":"*"},"D.S. 003-98-SA":{"esp":"Salud ocupacional","sec":"*"},"R.M. 312-2011-MINSA":{"esp":"Salud ocupacional","sec":"*"},"R.M. 571-2014-MINSA":{"esp":"Salud ocupacional","sec":"*"},"R.M. 375-2008-TR":{"esp":"Salud ocupacional","sec":"*"},"D.S. 015-2005-SA":{"esp":"Salud ocupacional","sec":"*"},"Ley 30102":{"esp":"Salud ocupacional","sec":"*"},"D.L. 1278":{"esp":"Ambiental","sec":"*"},"D.S. 014-2017-MINAM":{"esp":"Ambiental","sec":"*"},"D.S. 085-2003-PCM":{"esp":"Ambiental","sec":"*"},"Ley 28806 / D.S. 019-2006-TR":{"esp":"Fiscalización","sec":"*"}},"pais":{"cl":[{"c":"Código del Trabajo, art. 184","d":"Deber general de protección","a":"sst","s":"*","y":"2003","o":"Obliga al empleador a tomar todas las medidas necesarias para proteger la vida y la salud de sus trabajadores.","u":"https://www.bcn.cl/leychile/navegar?idNorma=207436"},{"c":"Ley 16.744","d":"Accidentes del trabajo y enfermedades profesionales","a":"sst","s":"*","y":"1968","o":"Obliga a cotizar el seguro laboral, a denunciar todo accidente y a que la mutual cubra atención y pensiones.","u":"https://www.bcn.cl/leychile/navegar?idNorma=28650"},{"c":"D.S. 101","d":"Reglamento de la Ley 16.744","a":"sst","s":"*","y":"1968","o":"Obliga a emitir la DIAT o la DIEP ante el organismo administrador apenas se conoce el accidente o la enfermedad.","u":"https://www.bcn.cl/leychile/navegar?idNorma=9231"},{"c":"D.S. 44","d":"Gestión preventiva de los riesgos laborales","a":"sst","s":"*","y":"2024 · rige desde el 1-feb-2025","o":"Obliga a matriz de peligros, mapa de riesgos, programa preventivo y comité paritario sobre 25 trabajadores. Reemplazó al D.S. 40 y derogó el D.S. 54.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1205298"},{"c":"D.S. 594","d":"Condiciones sanitarias y ambientales básicas","a":"salud","s":"*","y":"1999","o":"Obliga a dar agua potable, baños y ventilación, y a no superar 85 dB(A) ni los límites de agentes químicos.","u":"https://www.bcn.cl/leychile/navegar?idNorma=167766"},{"c":"D.S. 76","d":"Reglamento del art. 66 bis · contratistas","a":"sst","s":"*","y":"2006","o":"Obliga al mandante a llevar registro de contratistas y, sobre 50 trabajadores en obra, a implementar un sistema de gestión SST.","u":"https://www.bcn.cl/leychile/navegar?idNorma=257601"},{"c":"Ley 20.123","d":"Ley de subcontratación","a":"sst","s":"*","y":"2006","o":"Obliga al mandante a proteger a los trabajadores de sus contratistas en la obra, con responsabilidad solidaria o subsidiaria.","u":"https://www.bcn.cl/leychile/navegar?idNorma=254080"},{"c":"Ley 21.643","d":"Ley Karin · acoso y violencia laboral","a":"sst","s":"*","y":"2024 · rige desde el 1-ago-2024","o":"Obliga a tener protocolo de prevención del acoso y la violencia, y a investigar toda denuncia en máximo 30 días.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1200096"},{"c":"D.S. 21","d":"Reglamento de investigación de la Ley Karin","a":"sst","s":"*","y":"2024","o":"Fija cómo investigar: plazos, confidencialidad, medidas de resguardo inmediatas y envío del informe a la Dirección del Trabajo.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1204689"},{"c":"Ley 21.012","d":"Riesgo grave e inminente","a":"sst","s":"*","y":"2017","o":"Obliga a informar el riesgo grave e inminente y permite al trabajador paralizar faenas y evacuar sin represalias.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1103798"},{"c":"Ley 20.001","d":"Peso máximo de carga humana","a":"sst","s":"*","y":"2005 · límite de 25 kg desde 2016","o":"Prohíbe la carga manual sobre 25 kilos en hombres y 20 en mujeres y menores; la prohíbe del todo en embarazadas.","u":"https://www.bcn.cl/leychile/navegar?idNorma=235279"},{"c":"D.S. 63","d":"Reglamento del manejo manual de carga","a":"sst","s":"*","y":"2005","o":"Obliga a evaluar los riesgos del manejo manual de carga con el método oficial y a capacitar en técnicas seguras.","u":"https://www.bcn.cl/leychile/navegar?idNorma=241855"},{"c":"Ley 20.096","d":"Protección contra la radiación UV","a":"salud","s":"*","y":"2006","o":"Obliga a proteger a quien trabaja expuesto al sol: informar el índice UV y dar bloqueador, ropa y sombra.","u":"https://www.bcn.cl/leychile/navegar?idNorma=248323"},{"c":"D.S. 18","d":"Certificación de elementos de protección personal","a":"sst","s":"*","y":"1982","o":"Obliga a que todo elemento de protección personal usado en obra esté certificado por un organismo autorizado.","u":"https://www.bcn.cl/leychile/navegar?idNorma=7603"},{"c":"D.S. 28","d":"Hipobaria intermitente crónica por gran altitud","a":"salud","s":"mineria","y":"2012","o":"Obliga a exámenes de salud, aclimatación y oxígeno para quien trabaja sobre 3.000 metros. Se incorpora al D.S. 594.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1045465"},{"c":"D.S. 47 (OGUC)","d":"Ordenanza General de Urbanismo y Construcciones","a":"sst","s":"construccion","y":"1992","o":"Obliga a cerrar y señalizar la obra, y a proteger a peatones y vecinos durante faenas de construcción y demolición.","u":"https://www.bcn.cl/leychile/navegar?idNorma=8201"},{"c":"D.S. 132","d":"Reglamento de Seguridad Minera","a":"sst","s":"mineria","y":"2002","o":"Obliga a informar de inmediato al Sernageomin los accidentes fatales y a tener experto en prevención y reglamento interno.","u":"https://www.bcn.cl/leychile/navegar?idNorma=221064"},{"c":"D.S. 160","d":"Seguridad de instalaciones de combustibles líquidos","a":"sst","s":"hidrocarburos","y":"2008","o":"Obliga a inscribir las instalaciones ante la SEC y a mantener distancias, señalización y plan de emergencia.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1004120"},{"c":"D.S. 280","d":"Seguridad del transporte y distribución de gas de red","a":"sst","s":"hidrocarburos","y":"2009","o":"Obliga a diseñar y operar las redes de gas con personal autorizado y a reportar todo incidente a la SEC.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1012263"},{"c":"D.S. 8 (RIC)","d":"Seguridad de instalaciones de consumo eléctrico","a":"sst","s":"electrico","y":"2019","o":"Obliga a ejecutar las instalaciones eléctricas con instalador autorizado SEC, protección diferencial y puesta a tierra.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1143069"},{"c":"D.S. 43","d":"Almacenamiento de sustancias peligrosas","a":"sst","s":"*","y":"2015","o":"Obliga a almacenar las sustancias peligrosas separadas por incompatibilidad, en bodega autorizada, señalizada y con control de derrames.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1088802"},{"c":"D.S. 57","d":"Reglamento GHS de sustancias y mezclas peligrosas","a":"salud","s":"*","y":"2019","o":"Obliga a clasificar, etiquetar con pictogramas GHS y entregar la hoja de datos de seguridad de cada producto químico.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1155752"},{"c":"D.S. 298","d":"Transporte de cargas peligrosas","a":"sst","s":"*","y":"1994","o":"Obliga a rotular el vehículo, portar la hoja de seguridad y llevar conductor con curso vigente al transportar cargas peligrosas.","u":"https://www.bcn.cl/leychile/navegar?idNorma=12087"},{"c":"D.S. 10","d":"Reglamento de calderas y autoclaves","a":"sst","s":"industria","y":"2012","o":"Obliga a inscribir calderas y autoclaves ante la Seremi de Salud y a inspeccionarlas con operador acreditado.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1055319"},{"c":"Ley 19.300","d":"Bases generales del Medio Ambiente","a":"ambiente","s":"*","y":"1994","o":"Obliga a someter al SEIA los proyectos listados y a cumplir la resolución de calificación ambiental durante toda la obra.","u":"https://www.bcn.cl/leychile/navegar?idNorma=30667"},{"c":"D.S. 40 (MMA)","d":"Reglamento del SEIA","a":"ambiente","s":"*","y":"2012 · última reforma 21-ene-2026","o":"Define si el proyecto entra por DIA o por EIA y obliga a describir impactos, permisos ambientales y compromisos.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1053563"},{"c":"D.S. 148","d":"Reglamento sanitario de residuos peligrosos","a":"ambiente","s":"*","y":"2003","o":"Obliga a declarar los residuos peligrosos, almacenarlos hasta seis meses y entregarlos a destinatario autorizado con guía.","u":"https://www.bcn.cl/leychile/navegar?idNorma=226458"},{"c":"Ley 20.920","d":"Ley REP de reciclaje","a":"ambiente","s":"*","y":"2016","o":"Obliga a los productores de neumáticos, envases y otros productos prioritarios a financiar su recolección y cumplir metas.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1090894"},{"c":"D.S. 38 (MMA)","d":"Norma de emisión de ruido","a":"ambiente","s":"*","y":"2011","o":"Obliga a no superar los límites de ruido medidos en la vivienda vecina, según zona y horario diurno o nocturno.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1040928"},{"c":"D.S. 90","d":"Norma de emisión de RILes a aguas superficiales","a":"ambiente","s":"*","y":"2000","o":"Obliga a tratar y monitorear los residuos líquidos antes de descargarlos a ríos, lagos o mar, por parámetro.","u":"https://www.bcn.cl/leychile/navegar?idNorma=182637"},{"c":"Ley 20.551","d":"Cierre de faenas e instalaciones mineras","a":"ambiente","s":"mineria","y":"2011","o":"Obliga a toda faena minera a tener plan de cierre aprobado y garantía financiera antes de iniciar operaciones.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1032158"},{"c":"D.S. 41 (Minería)","d":"Reglamento de la ley de cierre de faenas","a":"ambiente","s":"mineria","y":"2012","o":"Detalla cómo elaborar, auditar y actualizar el plan de cierre y cómo se calcula la garantía ante el Sernageomin.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1045967"},{"c":"D.S. 248","d":"Reglamento de depósitos de relaves","a":"ambiente","s":"mineria","y":"2006","o":"Obliga a que el Sernageomin apruebe el diseño, la operación y el cierre de todo depósito de relaves antes de construirlo.","u":"https://www.bcn.cl/leychile/navegar?idNorma=259901"}],"co":[{"c":"Ley 9 de 1979","d":"Código Sanitario · Título III, salud ocupacional","a":"salud","s":"*","y":"1979","o":"Obliga al empleador a mantener ambiente de trabajo higiénico y seguro, programa permanente de medicina e higiene, y registrar accidentes.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=1177"},{"c":"Resolución 2400 de 1979","d":"Estatuto de Seguridad Industrial","a":"sst","s":"*","y":"1979","o":"Obliga a condiciones locativas seguras, orden y aseo, ventilación, servicios sanitarios, EPP y protección de máquinas.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=53565"},{"c":"Resolución 2013 de 1986","d":"COPASST · comité paritario","a":"sst","s":"*","y":"1986","o":"Obliga a conformar comité paritario con 10 o más trabajadores y a reunirlo al menos una vez al mes en horario laboral.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=5411"},{"c":"Decreto 2222 de 1993","d":"Higiene y seguridad en minería a cielo abierto","a":"sst","s":"mineria","y":"1993","o":"Obliga a controlar explosivos, taludes, transporte, ruido e instalaciones eléctricas y a prestar servicio médico en la mina.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=10679"},{"c":"Ley 99 de 1993","d":"Ley del medio ambiente · crea el SINA","a":"ambiente","s":"*","y":"1993","o":"Obliga a obtener licencia ambiental previa para obras que deterioren gravemente los recursos naturales, otorgada por la ANLA o la corporación regional.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=297"},{"c":"Decreto Ley 1295 de 1994","d":"Sistema General de Riesgos Laborales","a":"sst","s":"*","y":"1994","o":"Obliga a afiliar a todo trabajador a una ARL, pagar la cotización según clase de riesgo y reportar accidentes y enfermedades.","u":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=2629"},{"c":"Ley 1010 de 2006","d":"Acoso laboral","a":"sst","s":"*","y":"2006","o":"Obliga a incluir en el reglamento interno mecanismos de prevención del acoso laboral y un procedimiento interno confidencial.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=18843"},{"c":"Resolución 627 de 2006","d":"Norma de ruido y ruido ambiental","a":"ambiente","s":"construccion","y":"2006","o":"Obliga a no superar los límites de ruido por zona y horario: zona residencial 65 dB(A) de día y 55 de noche.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=19982"},{"c":"Resolución 1401 de 2007","d":"Investigación de incidentes y accidentes","a":"sst","s":"*","y":"2007","o":"Obliga a investigar todo incidente y accidente dentro de 15 días y a remitir los graves y mortales a la ARL.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=53497"},{"c":"Resolución 2646 de 2008","d":"Factores de riesgo psicosocial","a":"sst","s":"*","y":"2008","o":"Obliga a identificar y evaluar factores psicosociales intra y extralaborales y a vigilar epidemiológicamente el estrés ocupacional.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=31607"},{"c":"Ley 1562 de 2012","d":"Sistema de Riesgos Laborales · crea el SG-SST","a":"sst","s":"*","y":"2012","o":"Obliga a afiliar a la ARL a contratistas con contratos mayores a un mes y a reportar accidentes graves y mortales.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=48365"},{"c":"Decreto 1477 de 2014","d":"Tabla de enfermedades laborales","a":"salud","s":"*","y":"2014","o":"Obliga a usar la tabla oficial para calificar enfermedades laborales y orienta los programas de vigilancia por agente de riesgo.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=58849"},{"c":"Decreto 1072 de 2015","d":"Decreto Único del Sector Trabajo · Capítulo 6, SG-SST","a":"sst","s":"*","y":"2015","o":"Obliga a implementar y documentar el SG-SST: política, matriz de peligros, plan anual, responsable asignado, capacitación y plan de emergencias.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=62506"},{"c":"Decreto 472 de 2015","d":"Multas, clausura y paralización de obra","a":"sst","s":"*","y":"2015","o":"Permite al inspector clausurar el lugar de trabajo hasta 120 días y paralizar labores de inmediato por riesgo grave e inminente.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=61117"},{"c":"Decreto 1886 de 2015","d":"Seguridad en labores mineras subterráneas","a":"sst","s":"mineria","y":"2015","o":"Obliga a ventilación forzada, monitoreo de gases, autorrescatadores, planos actualizados, brigadas y refugios en toda mina subterránea.","u":"https://gestornormativo.creg.gov.co/gestor/entorno/docs/decreto_1886_2015.htm"},{"c":"Decreto 1076 de 2015","d":"Decreto Único del Sector Ambiente","a":"ambiente","s":"*","y":"2015","o":"Define qué proyectos requieren licencia ambiental y obliga a presentar estudio de impacto y plan de manejo antes de iniciar obra.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=62511"},{"c":"Decreto 1079 de 2015","d":"Transporte de mercancías peligrosas · Capítulo 7","a":"sst","s":"*","y":"2015","o":"Obliga a entregar la carga rotulada, dar tarjeta de emergencia al conductor, tener plan de contingencia y exigirle curso básico.","u":"https://rndc.mintransporte.gov.co/portals/0/DECRETO%201079%20DE%202015%20Capitulo%207.pdf"},{"c":"Resolución 631 de 2015","d":"Límites de vertimientos de agua residual","a":"ambiente","s":"industria","y":"2015","o":"Obliga a caracterizar el agua residual vertida y a cumplir los límites de DBO, DQO, sólidos, grasas y metales según la actividad.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=70346"},{"c":"Resolución 472 de 2017","d":"Residuos de construcción y demolición (RCD)","a":"ambiente","s":"construccion","y":"2017","o":"Obliga al gran generador a tener programa de manejo de RCD antes de iniciar obra y a reportar cada trimestre.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=68359"},{"c":"Resolución 0312 de 2019","d":"Estándares mínimos del SG-SST","a":"sst","s":"*","y":"2019","o":"Obliga a autoevaluar 7, 21 o 60 estándares mínimos según tamaño y riesgo, y a reportar el resultado cada año.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=82666"},{"c":"Resolución 5018 de 2019","d":"SST en el sector eléctrico","a":"sst","s":"electrico","y":"2019","o":"Obliga a aplicar lineamientos de SST en generación, transmisión, distribución y comercialización, incluidos contratistas en tareas de alto riesgo.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=88299"},{"c":"Resolución 491 de 2020","d":"Espacios confinados","a":"sst","s":"*","y":"2020","o":"Obliga a identificar y señalizar los espacios confinados, medir gases antes y durante, permiso de entrada, vigía y equipo de rescate.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=90906"},{"c":"Resolución 773 de 2021","d":"SGA · etiquetado de productos químicos","a":"sst","s":"industria","y":"2021","o":"Obliga a etiquetar los químicos con pictogramas SGA, tener la ficha de datos de seguridad accesible y capacitar cada año.","u":"https://normograma.supersalud.gov.co/compilacion/docs/resolucion_mtra_0773_2021.htm"},{"c":"Resolución 1257 de 2021","d":"Metas de aprovechamiento de RCD","a":"ambiente","s":"construccion","y":"2021","o":"Obliga a cumplir metas anuales de aprovechamiento de RCD y permite entregarlos a un receptor certificado avisando con 30 días.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=119018"},{"c":"Resolución 4272 de 2021","d":"Trabajo en alturas","a":"sst","s":"*","y":"2021 · rige desde el 8-ago-2022","o":"Obliga a programa de prevención de caídas, coordinador de alturas, permiso escrito, certificación de trabajadores y plan de rescate. Derogó la 1409 de 2012.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=120880"},{"c":"Resolución 2764 de 2022","d":"Batería de riesgo psicosocial","a":"sst","s":"*","y":"2022","o":"Obliga a aplicar la batería oficial de riesgo psicosocial cada año si el riesgo es alto y cada dos años si no.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=127124"},{"c":"Resolución 839 de 2023","d":"Registro RESPEL a través del RUA","a":"ambiente","s":"*","y":"2023 · rige desde el 1-ene-2026","o":"Obliga al generador de residuos peligrosos a inscribirse y reportar cada año en el RUA, entre febrero y abril.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=146438&dt=S"},{"c":"Ley 2365 de 2024","d":"Acoso sexual en el ámbito laboral","a":"sst","s":"*","y":"2024","o":"Obliga a tener política y protocolo interno contra el acoso sexual, con ruta de atención y publicación semestral de quejas y sanciones.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=157481"},{"c":"Resolución 40117 de 2024","d":"RETIE · nuevo Anexo General","a":"sst","s":"electrico","y":"2024","o":"Obliga a que toda instalación eléctrica se diseñe, construya e inspeccione bajo RETIE y se certifique antes de energizarla.","u":"https://gestornormativo.creg.gov.co/gestor/entorno/docs/resolucion_minminas_40117_2024.htm"},{"c":"Resolución 40537 de 2024","d":"Exploración y producción de hidrocarburos","a":"sst","s":"hidrocarburos","y":"2024","o":"Obliga a operar pozos bajo normas API/ISO, probar integridad y presión, y tener plan de contingencia y certificación de equipos.","u":"https://gestornormativo.creg.gov.co/gestor/entorno/docs/resolucion_minminas_40537_2024.htm"},{"c":"Ley 2466 de 2025","d":"Reforma laboral","a":"sst","s":"*","y":"2025","o":"Obliga a las empresas de plataformas digitales a pagar el cubrimiento de riesgos laborales de los trabajadores que las usan.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=181933"},{"c":"Resolución 3461 de 2025","d":"Comité de Convivencia Laboral","a":"sst","s":"*","y":"2025 · rige desde el 11-set-2025","o":"Obliga a conformar el comité de convivencia, recibir quejas en 5 días y cerrar el trámite preventivo en 65 días. Derogó la 652 y la 1356 de 2012.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=190589&dt=S"},{"c":"Resolución 40284 de 2026","d":"Modifica el RETIE","a":"sst","s":"electrico","y":"2026 · rige desde el 1-jul-2026","o":"Ajusta libros y anexos del RETIE: exime de certificación plena la autogeneración menor a 10 kVA y precisa alcances de los técnicos electricistas.","u":"https://gestornormativo.creg.gov.co/gestor/entorno/docs/resolucion_minminas_40284_2026.htm"}],"ar":[{"c":"Ley 19.587","d":"Higiene y Seguridad en el Trabajo","a":"sst","s":"*","y":"1972","o":"Obliga a capacitar al personal, hacer examen preocupacional y periódico, y proteger máquinas, ventilación, ruido y señalización.","u":"https://www.argentina.gob.ar/normativa/nacional/17612/texto"},{"c":"Decreto 351/79","d":"Reglamento general de higiene y seguridad","a":"sst","s":"*","y":"1979 · sigue vigente","o":"Fija valores exigibles de iluminación, ruido, ventilación, baños, matafuegos y salidas, y obliga a adecuar el establecimiento.","u":"https://www.argentina.gob.ar/normativa/nacional/decreto-351-1979-32030"},{"c":"Decreto 1338/96","d":"Servicios de medicina y de higiene y seguridad","a":"sst","s":"*","y":"1996","o":"Obliga a tener servicio de medicina del trabajo y de higiene y seguridad, con horas-profesional mensuales según dotación y riesgo.","u":"https://www.argentina.gob.ar/normativa/nacional/40574/actualizacion"},{"c":"Ley 24.557","d":"Ley de Riesgos del Trabajo","a":"sst","s":"*","y":"1995","o":"Obliga a afiliarse a una ART o autoasegurarse, denunciar cada accidente y garantizar las prestaciones médicas del trabajador.","u":"https://www.argentina.gob.ar/normativa/nacional/norma-27971/actualizacion"},{"c":"Ley 27.348","d":"Comisiones médicas obligatorias","a":"sst","s":"*","y":"2017","o":"Obliga al trabajador accidentado a pasar por la comisión médica jurisdiccional, con patrocinio letrado, antes de demandar judicialmente.","u":"https://www.argentina.gob.ar/normativa/nacional/ley-27348-2017-272119"},{"c":"Resolución SRT 463/09","d":"Relevamiento General de Riesgos Laborales","a":"sst","s":"*","y":"2009","o":"Obliga a presentar a la ART el relevamiento de riesgos del establecimiento y un plan de regularización de incumplimientos.","u":"https://www.argentina.gob.ar/normativa/nacional/153431/texto"},{"c":"Resolución SRT 299/11","d":"Constancia de entrega de EPP","a":"sst","s":"*","y":"2011","o":"Obliga a entregar EPP certificados y a registrar cada entrega en una constancia individual firmada por el trabajador.","u":"https://www.argentina.gob.ar/normativa/nacional/norma-180669/texto"},{"c":"Resolución MTEySS 295/03","d":"Ergonomía y agentes químicos","a":"sst","s":"*","y":"2003","o":"Obliga a respetar los límites de exposición a químicos, ruido y vibraciones y las pautas de levantamiento manual de cargas.","u":"https://servicios.infoleg.gob.ar/infolegInternet/anexos/90000-94999/90396/norma.htm"},{"c":"Resolución SRT 886/15","d":"Protocolo de Ergonomía","a":"sst","s":"*","y":"2015","o":"Obliga a evaluar el riesgo ergonómico de cada puesto, identificar los factores críticos y ejecutar medidas correctivas con plazos.","u":"https://www.argentina.gob.ar/normativa/nacional/norma-246272/texto"},{"c":"Resolución SRT 84/12","d":"Protocolo de iluminación","a":"sst","s":"*","y":"2012","o":"Obliga a medir la iluminación de cada puesto con el protocolo oficial firmado y a repetirla cada doce meses.","u":"https://servicios.infoleg.gob.ar/infolegInternet/anexos/190000-194999/193616/norma.htm"},{"c":"Resolución SRT 85/12","d":"Protocolo de ruido","a":"sst","s":"*","y":"2012","o":"Obliga a medir el nivel de ruido por puesto con el protocolo oficial y a corregir si supera el límite.","u":"https://servicios.infoleg.gob.ar/infolegInternet/anexos/190000-194999/193617/norma.htm"},{"c":"Resolución SRT 953/10","d":"Espacios confinados","a":"sst","s":"*","y":"2010","o":"Obliga a cumplir la IRAM 3625 antes de entrar: medir atmósfera, ventilar, permiso escrito y vigía en la boca.","u":"https://www.argentina.gob.ar/normativa/nacional/norma-169317/texto"},{"c":"Resolución SRT 30/23","d":"Carga térmica · estrés por calor","a":"sst","s":"*","y":"2023 · rige desde ene-2024","o":"Obliga a evaluar el estrés por calor con el índice TGBH y aplicar pausas o medidas al superar el límite.","u":"https://www.boletinoficial.gob.ar/detalleAviso/primera/291179/20230728"},{"c":"Resolución SRT 37/10","d":"Exámenes médicos","a":"salud","s":"*","y":"2010","o":"Obliga al preocupacional a cargo del empleador y al periódico a cargo de la ART cuando hay agentes de riesgo.","u":"https://www.argentina.gob.ar/normativa/nacional/163171/texto"},{"c":"Decreto 658/96","d":"Listado de enfermedades profesionales","a":"salud","s":"*","y":"1996","o":"Define qué enfermedad se reconoce como profesional según agente y tarea, y fija los agentes que disparan exámenes periódicos.","u":"https://www.argentina.gob.ar/normativa/nacional/37572/actualizacion"},{"c":"Resolución SRT 81/19","d":"Vigilancia de sustancias cancerígenas (SVCC)","a":"salud","s":"industria","y":"2019","o":"Obliga a inscribir el establecimiento, declarar cada 1 de abril los cancerígenos usados y guardar historias clínicas cuarenta años.","u":"https://www.argentina.gob.ar/normativa/nacional/norma-329835/texto"},{"c":"Resolución SRT 861/15","d":"Protocolo de contaminantes químicos","a":"sst","s":"industria","y":"2015","o":"Obliga a medir contaminantes químicos en aire con el protocolo oficial donde haya exposición y a compararlos contra los límites.","u":"https://www.argentina.gob.ar/normativa/nacional/resoluci%C3%B3n-861-2015-246217/texto"},{"c":"Resolución SRT 743/03","d":"Registro de accidentes industriales mayores (RENPRIAM)","a":"sst","s":"industria","y":"2003","o":"Obliga a declarar cada año antes del 15 de abril si se superan los umbrales de sustancias peligrosas almacenadas.","u":"https://www.argentina.gob.ar/srt/prevencion/registros-obligatorios"},{"c":"Resolución SRT 900/15","d":"Protocolo de puesta a tierra","a":"sst","s":"electrico","y":"2015","o":"Obliga a medir la resistencia de puesta a tierra y verificar la continuidad de masas, con protocolo firmado y validez anual.","u":"https://www.argentina.gob.ar/normativa/nacional/resoluci%C3%B3n-900-2015-246348/texto"},{"c":"Resolución SRT 3068/14","d":"Trabajos con tensión hasta 1 kV","a":"sst","s":"electrico","y":"2014","o":"Obliga a ejecutar los trabajos con tensión en baja tensión según el reglamento AEA y a habilitar al personal con plan de capacitación.","u":"https://www.boletinoficial.gob.ar/detalleAviso/primera/115737/20141120"},{"c":"Resolución SRT 11/22","d":"Trabajos con tensión mayor a 1 kV","a":"sst","s":"electrico","y":"2022","o":"Obliga a respetar las distancias de aproximación del reglamento AEA 2020 en alta tensión y a habilitar al personal.","u":"https://www.boletinoficial.gob.ar/detalleAviso/primera/258260/20220303"},{"c":"Decreto 911/96","d":"Higiene y seguridad en la construcción","a":"sst","s":"construccion","y":"1996","o":"Obliga a llevar legajo técnico en obra, asignar horas del servicio de higiene y seguridad y capacitar por niveles.","u":"https://www.argentina.gob.ar/normativa/nacional/decreto-911-1996-38568/actualizacion"},{"c":"Resolución SRT 231/96","d":"Condiciones básicas de obra y legajo técnico","a":"sst","s":"construccion","y":"1996","o":"Obliga al aviso de obra ante la ART antes de empezar y al legajo técnico firmado por el responsable.","u":"https://www.argentina.gob.ar/normativa/nacional/norma-40554/texto"},{"c":"Resolución SRT 51/97","d":"Aviso de obra y Programa de Seguridad","a":"sst","s":"construccion","y":"1997","o":"Obliga a avisar a la ART cinco días hábiles antes de iniciar y a tener Programa de Seguridad aprobado.","u":"https://www.argentina.gob.ar/normativa/nacional/44588/texto"},{"c":"Resolución SRT 319/99","d":"Obras repetitivas y de corta duración","a":"sst","s":"construccion","y":"1999","o":"Obliga al comitente a coordinar el servicio de higiene y a presentar programa para obras de hasta siete días.","u":"https://www.argentina.gob.ar/normativa/nacional/59941/texto"},{"c":"Resolución SRT 550/11","d":"Demolición, excavación y submuración","a":"sst","s":"construccion","y":"2011","o":"Obliga a Programa de Seguridad aprobado por la ART antes de demoler, excavar o submurar, con técnico presente permanentemente.","u":"https://www.argentina.gob.ar/normativa/nacional/181606/texto"},{"c":"Resolución SRT 503/14","d":"Movimiento de suelos y excavaciones","a":"sst","s":"construccion","y":"2014","o":"Obliga a entibar o taludar zanjas y pozos de más de 1,20 metros y a señalizar el perímetro.","u":"https://www.argentina.gob.ar/normativa/nacional/227747/texto"},{"c":"Resolución SRT 61/23","d":"Trabajo en altura en construcción","a":"sst","s":"construccion","y":"2023 · rige desde mar-2024","o":"Obliga a sumar al legajo técnico las listas de verificación de andamios, plataformas y sistemas anticaída, y a capacitar.","u":"https://www.boletinoficial.gob.ar/detalleAviso/primera/300086/20231206"},{"c":"Decreto 249/2007","d":"Higiene y seguridad en minería","a":"sst","s":"mineria","y":"2007","o":"Obliga a servicio de higiene y seguridad, plan de emergencia con brigada de incendio y registro foliado de capacitación.","u":"https://www.argentina.gob.ar/normativa/nacional/126637/texto"},{"c":"Ley 24.585","d":"Protección ambiental de la actividad minera","a":"ambiente","s":"mineria","y":"1995","o":"Obliga a presentar y obtener aprobación del informe de impacto ambiental antes de iniciar cualquier etapa minera.","u":"https://www.argentina.gob.ar/normativa/nacional/norma-30096/texto"},{"c":"Resolución SE 105/92","d":"Protección ambiental en exploración y explotación","a":"ambiente","s":"hidrocarburos","y":"1992","o":"Obliga a estudio ambiental antes del primer pozo y a monitoreos periódicos informados a la Secretaría de Energía.","u":"https://www.argentina.gob.ar/normativa/nacional/resoluci%C3%B3n-105-1992-25949/texto"},{"c":"Resolución SE 277/2025","d":"Registro de tanques aéreos de combustibles","a":"ambiente","s":"hidrocarburos","y":"2025","o":"Obliga a inscribir cada tanque aéreo y presentar declaración jurada de inspección API 653 firmada por inspector certificado.","u":"https://www.boletinoficial.gob.ar/detalleAviso/primera/327570/20250627"},{"c":"Resolución SE 119/2026","d":"Transporte de Hidrocarburos Líquidos","a":"sst","s":"hidrocarburos","y":"2026 · rige desde may-2026","o":"Obliga a diseñar, operar y gestionar la integridad de los ductos interprovinciales según la ASME B31.4 edición 2022.","u":"https://www.boletinoficial.gob.ar/detalleAviso/primera/342162/20260520"},{"c":"Ley 25.675","d":"Ley General del Ambiente","a":"ambiente","s":"*","y":"2002","o":"Obliga a evaluar el impacto ambiental antes de obras que degraden el ambiente y a contratar seguro de recomposición.","u":"https://www.argentina.gob.ar/normativa/nacional/ley-25675-79980/texto"},{"c":"Ley 24.051","d":"Residuos peligrosos (con el Decreto 831/93)","a":"ambiente","s":"*","y":"1991","o":"Obliga a inscribirse como generador, emitir manifiesto por cada carga y entregar solo a transportistas y operadores habilitados.","u":"https://www.argentina.gob.ar/normativa/nacional/ley-24051-450/actualizacion"}],"uy":[{"c":"Ley 16.074","d":"Seguro de accidentes del trabajo y enfermedades profesionales","a":"sst","s":"*","y":"1989","o":"Hace obligatorio el seguro del BSE y obliga al empleador a denunciar el accidente dentro de las 72 horas en Montevideo y de los 5 días hábiles en el interior.","u":"https://www.impo.com.uy/bases/leyes/16074-1989"},{"c":"Decreto 125/014","d":"Seguridad y salud en la construcción","a":"sst","s":"construccion","y":"2014","o":"Reglamenta el Convenio 167 de la OIT: es el reglamento de seguridad e higiene de la construcción. Exige al menos dos horas de capacitación antes de que el trabajador empiece su tarea, y reglamenta el trabajo vertical.","u":"https://www.impo.com.uy/bases/decretos/125-2014"},{"c":"Decreto 291/007","d":"Prevención de los riesgos de cualquier actividad","a":"sst","s":"*","y":"2007","o":"Reglamenta el Convenio 155 de la OIT: la gestión de la seguridad y salud en toda actividad, con participación de los trabajadores; crea las comisiones tripartitas sectoriales.","u":"https://www.impo.com.uy/bases/decretos/291-2007"},{"c":"Decreto 127/014","d":"Servicios de prevención y salud en el trabajo","a":"salud","s":"*","y":"2014","o":"Reglamenta el Convenio 161 de la OIT: los servicios de salud en el trabajo, que se van incorporando por sector de actividad.","u":"https://www.impo.com.uy/bases/decretos/127-2014"},{"c":"Ley 19.196","d":"Responsabilidad penal del empleador","a":"sst","s":"*","y":"2014","o":"Castiga con 3 a 24 meses de prisión al empleador que no adopta las medidas de seguridad y pone en peligro grave la vida, la salud o la integridad física del trabajador.","u":"https://www.impo.com.uy/bases/leyes/19196-2014"},{"c":"Ley 17.283","d":"Protección del medio ambiente","a":"ambiente","s":"*","y":"2000","o":"Declara de interés general la protección del ambiente, de la calidad del aire, del agua, del suelo y del paisaje.","u":"https://www.impo.com.uy/bases/leyes/17283-2000"},{"c":"Ley 16.466","d":"Evaluación del impacto ambiental","a":"ambiente","s":"construccion","y":"1994","o":"Las obras de su lista —carreteras, puentes, puertos, proyectos urbanísticos, entre otras— necesitan autorización ambiental previa antes de ejecutarse.","u":"https://www.impo.com.uy/bases/leyes/16466-1994"},{"c":"Ley 19.829","d":"Gestión integral de residuos","a":"ambiente","s":"*","y":"2019","o":"Incluye los residuos de la construcción, reforma o demolición de obras y prevé planes de gestión de residuos para cada generador.","u":"https://www.impo.com.uy/bases/leyes/19829-2019"}],"py":[{"c":"Ley 5804","d":"Sistema Nacional de Prevención de Riesgos Laborales","a":"sst","s":"*","y":"","o":"Establece el Sistema Nacional de Prevención de Riesgos Laborales.","u":"https://www.bacn.gov.py/leyes-paraguayas/9127/ley-n-5804-establece-el-sistema-nacional-de-prevencion-de-riesgos-laborales"},{"c":"Decreto 14.390/92","d":"Reglamento General Técnico de Seguridad, Higiene y Medicina en el Trabajo","a":"sst","s":"*","y":"1992","o":"Es el reglamento técnico general de seguridad, higiene y medicina en el trabajo.","u":"https://informacionpublica.paraguay.gov.py/public/1585826-DECRETON14390-92pdf-DECRETON14.390-92.pdf"},{"c":"Ley 294/93","d":"Evaluación de impacto ambiental","a":"ambiente","s":"*","y":"1993","o":"Es la ley bajo la que cada proyecto presenta su relatorio de impacto ambiental (RIMA) al MADES; la reglamenta el Decreto 453/13.","u":"https://www.mades.gov.py/"}],"mx":[{"c":"Ley Federal del Trabajo","d":"Título Noveno · Riesgos de trabajo","a":"sst","s":"*","y":"1970 · texto vigente","o":"Obliga al patrón a dar aviso por escrito a la STPS de los accidentes de trabajo dentro de las 72 horas (art. 504, fr. V).","u":"https://www.diputados.gob.mx/LeyesBiblio/pdf/LFT.pdf"},{"c":"Reglamento Federal de Seguridad y Salud en el Trabajo","d":"El reglamento general de SST","a":"sst","s":"*","y":"2014","o":"Obliga a contar con un diagnóstico y un programa de seguridad y salud, a constituir la comisión de seguridad e higiene y a avisar a la STPS de los accidentes (art. 7).","u":"https://dof.gob.mx/nota_detalle.php?codigo=5368114&fecha=13/11/2014"},{"c":"NOM-030-STPS-2009","d":"Servicios preventivos de seguridad y salud","a":"sst","s":"*","y":"2009","o":"Obliga a designar un responsable de SST, a tener un diagnóstico y un programa de seguridad y salud actualizado al menos cada año (con menos de 100 trabajadores, una relación de acciones).","u":"https://asinom.stps.gob.mx/upload/nom/32.pdf"},{"c":"NOM-019-STPS-2011","d":"Comisiones de seguridad e higiene","a":"sst","s":"*","y":"2011","o":"Obliga a constituir al menos una comisión en todo centro de trabajo, con recorridos de verificación al menos cada tres meses y capacitación de sus integrantes.","u":"https://asinom.stps.gob.mx/upload/nom/34.pdf"},{"c":"NOM-031-STPS-2011","d":"Construcción · condiciones de seguridad y salud","a":"sst","s":"construccion","y":"2011","o":"Obliga, en toda obra, a dar el EPP básico y el específico; en las medianas y grandes, a tener el análisis de riesgos potenciales, un sistema de seguridad y salud en la obra y capacitación.","u":"https://asinom.stps.gob.mx/upload/noms/NOM-031.pdf"},{"c":"NOM-009-STPS-2011","d":"Trabajos en altura","a":"sst","s":"*","y":"2011","o":"Aplica sobre 1.80 m. Obliga al análisis previo de las condiciones, a autorizar por escrito los trabajos en andamios y plataformas, a capacitar y a los exámenes médicos.","u":"https://asinom.stps.gob.mx/upload/nom/35.pdf"},{"c":"NOM-017-STPS-2024","d":"Equipo de protección personal · selección, uso y manejo","a":"sst","s":"*","y":"DOF 28-03-2025 · reemplazó a la NOM-017-STPS-2008","o":"Obliga a analizar los riesgos por puesto, a dar el EPP adecuado y a capacitar antes de empezar, con repaso al menos cada dos años.","u":"https://dof.gob.mx/normasOficiales/9496/stps/stps.html"},{"c":"NOM-026-STPS-2008","d":"Colores y señales de seguridad","a":"sst","s":"*","y":"2008","o":"Obliga a usar los colores y señales de la norma, a capacitar para entenderlos y a mantenerlos visibles y legibles.","u":"https://asinom.stps.gob.mx/upload/noms/Nom-026.pdf"},{"c":"NOM-002-STPS-2010","d":"Prevención y protección contra incendios","a":"sst","s":"*","y":"2010","o":"Obliga a clasificar el riesgo de incendio, a tener el croquis con rutas y equipos, un plan de emergencia y simulacros: uno al año (riesgo ordinario) o dos (riesgo alto).","u":"https://asinom.stps.gob.mx/upload/nom/33.pdf"},{"c":"NOM-033-STPS-2015","d":"Trabajos en espacios confinados","a":"sst","s":"*","y":"2015","o":"Obliga a analizar los riesgos antes de entrar, a autorizar por escrito cada trabajo, a designar responsable y vigía y a medir la atmósfera.","u":"https://asinom.stps.gob.mx/upload/nom/44.pdf"},{"c":"NOM-035-STPS-2018","d":"Factores de riesgo psicosocial","a":"salud","s":"*","y":"2018","o":"Obliga a una política de prevención, a identificar a quien vivió un acontecimiento traumático severo y, desde 16 trabajadores, a analizar los factores de riesgo psicosocial.","u":"https://asinom.stps.gob.mx/upload/nom/48.pdf"},{"c":"LGEEPA","d":"Ley General del Equilibrio Ecológico y la Protección al Ambiente","a":"ambiente","s":"*","y":"1988 · última reforma 19-01-2026","o":"Las obras de su lista —vías generales de comunicación, desarrollos inmobiliarios en ecosistemas costeros, cambios de uso del suelo forestal, entre otras— necesitan la autorización de impacto ambiental de la SEMARNAT.","u":"https://www.diputados.gob.mx/LeyesBiblio/pdf/LGEEPA.pdf"},{"c":"LGPGIR","d":"Ley General para la Prevención y Gestión Integral de los Residuos","a":"ambiente","s":"*","y":"2003 · última reforma 19-01-2026","o":"Es la ley de los residuos: de ella cuelga la NOM-161, que obliga a tener plan de manejo para los residuos de la obra. Se reformó en 2026 con la Ley General de Economía Circular.","u":"https://www.diputados.gob.mx/LeyesBiblio/ref/lgpgir.htm"},{"c":"NOM-161-SEMARNAT-2011","d":"Residuos de manejo especial sujetos a plan de manejo","a":"ambiente","s":"construccion","y":"2011 · DOF 01-02-2013","o":"Los residuos de la construcción, mantenimiento y demolición que se generen en una obra en cantidad mayor a 80 m³ necesitan plan de manejo.","u":"https://www.profepa.gob.mx/innovaportal/file/6633/1/nom-161-semarnat-2011.pdf"}],"us":[{"c":"OSH Act of 1970, Section 5","d":"Deberes del empleador y del trabajador","a":"sst","s":"*","y":"1970","o":"Obliga al empleador a dar un lugar de trabajo libre de peligros reconocidos que causen o puedan causar la muerte o daño físico grave, y a cumplir las normas de OSHA; el trabajador también debe cumplirlas.","u":"https://www.osha.gov/laws-regs/oshact/section5-duties"},{"c":"29 CFR 1904","d":"Registro y reporte de lesiones y enfermedades","a":"sst","s":"*","y":"texto vigente","o":"Obliga a reportar a OSHA una muerte dentro de las 8 horas y una hospitalización, amputación o pérdida de un ojo dentro de las 24. Con 10 trabajadores o menos no se lleva el registro, pero se reporta igual.","u":"https://www.osha.gov/laws-regs/regulations/standardnumber/1904/1904.39"},{"c":"29 CFR 1926.21","d":"Construcción · capacitación en seguridad","a":"sst","s":"construccion","y":"texto vigente","o":"Obliga a instruir a cada trabajador para reconocer y evitar las condiciones inseguras y en las normas que aplican a su trabajo.","u":"https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.21"},{"c":"29 CFR 1926 Subpart M","d":"Construcción · protección contra caídas","a":"sst","s":"construccion","y":"texto vigente","o":"Obliga a proteger a quien trabaja junto a un borde a 6 pies (1.8 m) o más: baranda, red de seguridad o sistema personal de detención de caídas.","u":"https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.501"},{"c":"29 CFR 1926 Subpart L","d":"Construcción · andamios","a":"sst","s":"construccion","y":"texto vigente","o":"Obliga a proteger contra caídas sobre 10 pies (3.1 m) y a que una persona competente inspeccione el andamio antes de cada turno.","u":"https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.451"},{"c":"29 CFR 1926 Subpart P","d":"Construcción · excavaciones","a":"sst","s":"construccion","y":"texto vigente","o":"Obliga a proteger contra derrumbes a quien trabaja en una excavación; no hace falta en roca estable o bajo 5 pies (1.52 m) si una persona competente revisó el terreno.","u":"https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.652"},{"c":"29 CFR 1926 Subpart AA","d":"Construcción · espacios confinados","a":"sst","s":"construccion","y":"texto vigente","o":"Obliga a que una persona competente identifique los espacios confinados antes de empezar y, si se va a entrar a uno con permiso, a tener un programa escrito de permisos.","u":"https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1203"},{"c":"29 CFR 1926.1153","d":"Construcción · sílice cristalina respirable","a":"salud","s":"construccion","y":"texto vigente","o":"Obliga a que nadie se exponga a más de 50 µg/m³ de sílice cristalina respirable (promedio de 8 horas) y a un plan escrito de control de la exposición.","u":"https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1153"},{"c":"29 CFR 1910.1200","d":"Comunicación de peligros (químicos)","a":"salud","s":"*","y":"texto vigente","o":"Obliga a un programa escrito, a rotular cada envase, a tener a mano las hojas de datos de seguridad (SDS) y a capacitar al trabajador desde su primer día con el producto.","u":"https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.1200"},{"c":"Clean Water Act · NPDES (construcción)","d":"Aguas de lluvia de la obra","a":"ambiente","s":"construccion","y":"—","o":"La obra que remueve 1 acre o más de terreno (o menos, si es parte de un plan mayor) necesita cobertura de un permiso NPDES para sus aguas de lluvia, de la EPA o del estado.","u":"https://www.epa.gov/npdes/stormwater-discharges-construction-activities"},{"c":"40 CFR 61, Subpart M","d":"Asbesto en demoliciones y remodelaciones (NESHAP)","a":"ambiente","s":"construccion","y":"—","o":"Antes de demoler o remodelar hay que inspeccionar si hay asbesto y avisar a la agencia delegada (por lo general, la del estado) cuando se supera la cantidad fijada.","u":"https://www.epa.gov/asbestos/asbestos-national-emission-standards-hazardous-air-pollutants-neshap"},{"c":"40 CFR 745, Subpart E","d":"Plomo en remodelaciones (RRP)","a":"salud","s":"construccion","y":"—","o":"Quien cobra por trabajos que alteran superficies pintadas en viviendas, guarderías y preescolares construidos antes de 1978 tiene que estar certificado y trabajar con prácticas seguras frente al plomo.","u":"https://www.epa.gov/lead/lead-renovation-repair-and-painting-program"}],"ca":[{"c":"Canada Labour Code, Part II","d":"SST de las empresas de jurisdicción federal","a":"sst","s":"*","y":"texto vigente","o":"Rige solo para las empresas de jurisdicción federal (aviación, bancos, telecomunicaciones, ferrocarriles interprovinciales, correo, puertos…). La mayoría de las obras se rigen por la ley de su provincia.","u":"https://laws-lois.justice.gc.ca/eng/acts/L-2/"},{"c":"Occupational Health and Safety Act (Ontario)","d":"La ley de SST de Ontario","a":"sst","s":"*","y":"R.S.O. 1990, c. O.1","o":"Obliga a avisar de inmediato la muerte o una lesión grave a un inspector del Ministerio de Trabajo y al comité, con informe escrito en 48 horas; el accidente con tiempo perdido, por escrito al comité en 4 días.","u":"https://www.ontario.ca/laws/statute/90o01"},{"c":"O. Reg. 213/91 (Ontario)","d":"Construction Projects","a":"sst","s":"construccion","y":"1991 · texto vigente","o":"Obliga a proteger contra caídas de más de 3 m —y en una abertura del piso, a cualquier altura— y a probar que el trabajador hizo un curso de trabajo en altura aprobado.","u":"https://www.ontario.ca/laws/regulation/910213"},{"c":"Loi sur la santé et la sécurité du travail (Québec)","d":"La ley de SST de Quebec (S-2.1)","a":"sst","s":"*","y":"texto vigente","o":"Obliga a avisar a la CNESST por el medio más rápido de una muerte, de la pérdida de un miembro o de una lesión grave, con informe escrito dentro de las 24 horas (art. 62).","u":"https://www.legisquebec.gouv.qc.ca/fr/document/lc/S-2.1"},{"c":"Code de sécurité pour les travaux de construction (Québec)","d":"S-2.1, r. 4","a":"sst","s":"construccion","y":"texto vigente","o":"Obliga a poner barandas donde hay riesgo de caída de más de 3 m; si no se puede, protección contra caídas según la jerarquía de medidas (art. 2.9.1).","u":"https://www.legisquebec.gouv.qc.ca/fr/document/rc/S-2.1,%20r.%204"},{"c":"O. Reg. 406/19 (Ontario)","d":"Manejo del suelo excedente de la obra","a":"ambiente","s":"construccion","y":"2019","o":"El responsable del proyecto evalúa los usos anteriores del terreno, hace el plan de muestreo, registra ciertos proyectos en el Excess Soil Registry y sigue el rastro del suelo que sale de la obra.","u":"https://www.ontario.ca/page/handling-excess-soil"},{"c":"Loi sur la qualité de l'environnement (Québec)","d":"Calidad del ambiente","a":"ambiente","s":"*","y":"—","o":"Clasifica las actividades según su riesgo ambiental: las de riesgo moderado necesitan autorización del ministro antes de empezar.","u":"https://www.environnement.gouv.qc.ca/lqe/autorisations/index.htm"}],"do":[{"c":"Ley 16-92","d":"Código de Trabajo","a":"sst","s":"*","y":"1992","o":"Es la base: el reglamento de SST sale de su art. 420, y las multas por incumplirlo, de su Libro Octavo.","u":"https://mt.gob.do/wp-content/uploads/2024/07/codigo_de_trabajo.pdf"},{"c":"Decreto 522-06","d":"Reglamento de Seguridad y Salud en el Trabajo","a":"sst","s":"*","y":"2006","o":"Obliga a evitar y controlar los riesgos, dar el EPP gratis (7.9), registrar los accidentes (6.1.3) y capacitar a cada trabajador en los riesgos de su puesto, con registro por persona (9.3 y 9.6).","u":"https://mt.gob.do/wp-content/uploads/2023/06/Reglamento-522-06.pdf"},{"c":"Decreto 522-06, art. 8","d":"Programa de Seguridad y Salud en el Trabajo","a":"sst","s":"*","y":"2006","o":"Obliga a remitir el programa de SST al Ministerio de Trabajo entre julio y septiembre y a actualizarlo cada 3 años. La empresa nueva tiene 3 meses desde que inicia actividades.","u":"https://mt.gob.do/wp-content/uploads/2023/06/Reglamento-522-06.pdf"},{"c":"Decreto 522-06, arts. 4.3 y 11","d":"Riesgo grave e inminente","a":"sst","s":"*","y":"2006","o":"El trabajador puede interrumpir su actividad ante un riesgo grave e inminente, agotados los canales internos. El empleador debe dejarlo retirarse y no puede exigirle volver mientras siga el peligro (art. 12: sin perjuicio para él).","u":"https://mt.gob.do/wp-content/uploads/2023/06/Reglamento-522-06.pdf"},{"c":"Decreto 522-06, art. 10","d":"Coordinación con contratistas","a":"sst","s":"*","y":"2006","o":"Si varias empresas trabajan en el mismo lugar, todas coordinan la prevención, y el titular del lugar informa a los contratistas de los riesgos y de las medidas de emergencia.","u":"https://mt.gob.do/wp-content/uploads/2023/06/Reglamento-522-06.pdf"},{"c":"Decreto 522-06, art. 7.14","d":"Vigilancia de la salud","a":"salud","s":"*","y":"2006","o":"Obliga a exámenes médicos periódicos según el riesgo, nunca con más de un año entre uno y otro, hechos o supervisados por médico con especialidad o maestría en salud ocupacional.","u":"https://mt.gob.do/wp-content/uploads/2023/06/Reglamento-522-06.pdf"},{"c":"Resolución 04/2007","d":"Condiciones generales y particulares de SST","a":"sst","s":"*","y":"2007","o":"Fija las condiciones del lugar de trabajo: botiquín en todo lugar de trabajo (1.20), puestos de primeros auxilios con 100 o más trabajadores por turno (1.21), barandillas rígidas de 90 cm como mínimo (1.26) y protectores auditivos sobre 80 dB(A) (3.1.5.2).","u":"https://mt.gob.do/wp-content/uploads/2023/06/Reglamento-522-06.pdf"},{"c":"Resolución 04/2007, 1.35 y 2.46","d":"Escaleras y cargas suspendidas","a":"sst","s":"construccion","y":"2007","o":"Desde una escalera de mano, sobre 2.44 m (8 pies) solo con cinturón de seguridad (1.35.15); escaleras fijas de más de 2.44 m con protección circundante (1.35.10); nadie debajo de una carga suspendida (2.46).","u":"https://mt.gob.do/wp-content/uploads/2023/06/Reglamento-522-06.pdf"},{"c":"Resolución 04/2007, parte II, 2.3","d":"Construcciones","a":"sst","s":"construccion","y":"2007","o":"La sección propia de las obras. La app todavía no la resume: antes de citar una medida de andamios, excavaciones o altura, ábrela en el texto oficial.","u":"https://mt.gob.do/wp-content/uploads/2023/06/Reglamento-522-06.pdf"},{"c":"Comité Mixto de SST","d":"Manual-Guía del Ministerio de Trabajo (2024)","a":"sst","s":"*","y":"2024","o":"Con 15 o más trabajadores, Comité Mixto paritario: preside el empleador y el secretario es de los trabajadores; se reúne por lo menos una vez al mes y manda sus actas a la Dirección General de Higiene y Seguridad Industrial. Con menos de 15, un Coordinador de SST.","u":"https://mt.gob.do/wp-content/uploads/2024/09/Manual-Guia-para-Conformacion-del-CM.pdf"},{"c":"Proyecto de reforma del 522-06","d":"En consulta pública desde octubre de 2023","a":"sst","s":"*","y":"no vigente","o":"El Ministerio de Trabajo consultó un reglamento nuevo. Mientras no se promulgue manda el Decreto 522-06, que el Ministerio sigue publicando como vigente.","u":"https://transparencia.mt.gob.do/index.php/consulta-publica/category/consulta-publica-del-proyecto-de-modificacion-del-decreto-522-06"},{"c":"Ley 87-01","d":"Sistema Dominicano de Seguridad Social","a":"salud","s":"*","y":"2001","o":"Crea el Seguro de Riesgos Laborales: el trabajador inscrito en la TSS queda cubierto por accidente de trabajo, de trayecto y enfermedad profesional.","u":"https://idoppril.gob.do/download/sobre-sistema-de-seguridad-social-ley-87-01/"},{"c":"Ley 397-19","d":"Crea el IDOPPRIL","a":"salud","s":"*","y":"2019","o":"El IDOPPRIL administra el Seguro de Riesgos Laborales. Ahí se notifica el accidente de trabajo (formulario ATR-2) y la enfermedad profesional (EPR-1).","u":"https://idoppril.gob.do/download/que-crea-el-instituto-dominicano-de-prevencion-y-proteccion-de-riegos-laborales-y-modifica-ley-87-01-ley-no-397-19/"},{"c":"Reglamento del Seguro de Riesgos Laborales, art. 36","d":"Aviso del accidente de trabajo","a":"salud","s":"*","y":"Ley 87-01","o":"Obliga al empleador a notificar el accidente a la administradora —hoy el IDOPPRIL— dentro de las 72 horas hábiles (3 días laborables). Si no avisa, el trabajador reclama directo.","u":"https://www.tss.gob.do/assets/regla_srl_v2.pdf"},{"c":"Ley 64-00","d":"Ley General sobre Medio Ambiente y Recursos Naturales","a":"ambiente","s":"*","y":"2000","o":"Obliga a tener la autorización ambiental antes de ejecutar una obra que pueda afectar el ambiente (arts. 40 y 41: incluye carreteras y proyectos de desarrollo urbano).","u":"https://ambiente.gob.do/wpfd_file/ley-64-00-general-sobre-medio-ambiente-y-recursos-naturales/"},{"c":"Ley 225-20","d":"Gestión integral y coprocesamiento de residuos sólidos","a":"ambiente","s":"*","y":"2020","o":"Obliga a separar los residuos en la fuente (art. 17). Los de construcción y demolición son una categoría propia de la ley.","u":"https://ambiente.gob.do/wpfd_file/ley-no-225-20-gestion-residuos-solidos/"},{"c":"Decreto 320-21","d":"Reglamento de la Ley 225-20","a":"ambiente","s":"*","y":"2021","o":"Reglamento de aplicación de la ley de residuos: baja a detalle cómo cumplirla.","u":"https://ambiente.gob.do/wpfd_file/reglamento-de-aplicacion-de-la-ley-num-225-20-general-de-gestion-integral-y-coprocesamiento-de-residuos-solidos/"},{"c":"NA-RU-001-03","d":"Norma ambiental de protección contra ruidos","a":"ambiente","s":"*","y":"2003","o":"Fija los niveles máximos permisibles del ruido ambiental de fuentes fijas y móviles: es la que mide el ruido que la obra saca a los vecinos.","u":"https://ambiente.gob.do/wpfd_file/normas-ambientales-para-la-proteccion-contra-ruidos/"},{"c":"Ley 172-13","d":"Protección de los datos personales","a":"salud","s":"*","y":"2013","o":"Rige cómo la empresa trata los datos de su personal: fichas, fotos, firmas y exámenes.","u":"https://presidencia.gob.do/sites/default/files/statics/transparencia/marco-legal/leyes/Ley-172-13.pdf"}]},"vacios":{"cl":[{"c":"Trabajo en altura","d":"Chile no tiene un decreto propio","o":"No hay reglamento chileno dedicado al trabajo en altura. La obligación de arnés, barandas y puntos de anclaje cuelga del art. 184 del Código del Trabajo y de la matriz de riesgos del D.S. 44.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1205298","e":"Marco legal"},{"c":"Espacios confinados","d":"Chile no tiene un decreto propio","o":"No hay reglamento chileno dedicado. La obligación sale del D.S. 594 (ventilación y agentes químicos) y de la matriz del D.S. 44. La NCh 3386 existe pero es voluntaria, no es ley.","u":"https://www.bcn.cl/leychile/navegar?idNorma=167766","e":"Marco legal"},{"c":"Ojo con el nombre","d":"El D.S. 40 de SST ya no existe","o":"Fue reemplazado por el D.S. 44, vigente desde el 1 de febrero de 2025, que también derogó el D.S. 54 de comités paritarios. El «D.S. 40» que sigue vivo es el del SEIA, que es ambiental y es otra cosa.","u":"https://www.bcn.cl/leychile/navegar?idNorma=1205298","e":"Marco legal"}],"ar":[{"c":"Altura fuera de construcción","d":"No hay norma nacional propia","o":"La Resolución SRT 61/23 es solo para construcción. En industria y minería la obligación sale del Decreto 351/79 y de la Resolución MTEySS 295/03.","u":"https://www.argentina.gob.ar/normativa/nacional/decreto-351-1979-32030","e":"Marco legal"},{"c":"Baja de 122 normas","d":"Resolución SRT 35/2026","o":"El 28 de julio de 2026 la SRT dio de baja 122 normas de riesgos del trabajo. Ninguna de esta lista figura derogada, pero antes de usar una en un legajo conviene abrir el anexo oficial.","u":"https://www.boletinoficial.gob.ar/","e":"Marco legal"}],"co":[{"c":"Lo que ya no se cita","d":"Normas derogadas que siguen circulando","o":"La Resolución 1409 de 2012 de alturas la derogó la 4272 de 2021; la 652 y la 1356 de 2012 de convivencia las derogó la 3461 de 2025; la 2404 de 2019 la derogó la 2764 de 2022.","u":"https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=120880","e":"Marco legal"}],"do":[]},"esp":["Marco legal","Construcción","Minería","Hidrocarburos","Eléctrico","Salud ocupacional","Ambiental","Fiscalización","Otras"],"pie":{"Marco legal":"La ley de SST, su reglamento y los registros que exige. Manda en los cuatro sectores.","Construcción":"Solo para obra: edificación, montaje y habilitación urbana.","Minería":"Solo para minería: interior mina, tajo y planta concentradora.","Hidrocarburos":"Solo para hidrocarburos: refinería, planta de proceso y almacenamiento.","Eléctrico":"Trabajos con electricidad. Aplica en cualquier sector, no solo en las eléctricas.","Salud ocupacional":"Exámenes médicos, ergonomía, agentes químicos, SCTR y radiación solar.","Ambiental":"Residuos sólidos y ruido. Lo que cruza con la licencia y con la comunidad.","Fiscalización":"Cómo actúa SUNAFIL y cuánto cuesta incumplir.","Otras":"PDF cargados que todavía no tienen resumen escrito en la app."},"campo":{"General":"Marco legal","Construccion":"Construcción","Mineria":"Minería","Hidrocarburos":"Hidrocarburos","Electrico":"Eléctrico","Salud ocupacional":"Salud ocupacional","Ambiental":"Ambiental","Fiscalizacion":"Fiscalización"},"espSec":{"Construcción":"construccion","Minería":"mineria","Hidrocarburos":"hidrocarburos"},"secIc":{"construccion":"🏗️","mineria":"⛏️","industria":"🏭","hidrocarburos":"🛢️"},"sectores":[{"id":"construccion","nombre":"Construcción","icono":"🏗️","pie":"Obra, edificación y montaje"},{"id":"mineria","nombre":"Minería","icono":"⛏️","pie":"Interior mina, tajo y planta concentradora"},{"id":"industria","nombre":"Industria","icono":"🏭","pie":"Planta de producción y manufactura"},{"id":"hidrocarburos","nombre":"Hidrocarburos","icono":"🛢️","pie":"Refinería, planta de proceso y almacenamiento"}],"descartadas":["D.S. 011-2019-TR - Reglamento de SST para el sector Construccion - Construccion.pdf","D.S. 023-2017-EM - Modificatoria del Reglamento de SSO en Mineria - Mineria.pdf"]};
